package api.openapi_p.aichat_p; import org.junit.jupiter.api.*; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AiChatControllerTest { @Mock AiChatService service; @InjectMocks AiChatController controller; @Test @DisplayName("UT-BE-AICHAT-CTRL-001 질문에 대한 챗봇 응답을 반환한다") void chat(){ AiChatRequestDTO r=new AiChatRequestDTO(); AiChatResponseDTO x=new AiChatResponseDTO(); when(service.chat(r)).thenReturn(x); assertThat(controller.chat(r)).isSameAs(x); } }
